#!/usr/bin/env bash
# Build Luma's initramfs for the Surface Duo 2: postmarketOS's, unmodified.
#
# Luma's Fairphone 6 boots through postmarketOS edge's postmarketos-initramfs,
# generated by postmarketOS's own mkinitfs, with a small Luma overlay on top
# (docs/devices.md in the Luma tree). This does the first part the same way,
# in an Alpine edge arm64 container with the postmarketOS edge repository:
# install postmarketos-initramfs and postmarketos-mkinitfs, give mkinitfs the
# Duo 2's deviceinfo and our msm-5.4 module tree, and let it write the archive.
#
# The postmarketOS signing key is fetched from postmarketOS's pmbootstrap
# repository at build time and checked against a pinned hash; it is not kept
# in this repository.
#
# Usage: duo2-mkinitramfs-pmos.sh   writes build/duo2-initramfs/initramfs-luma
#                                   (postmarketOS archive + Duo 2 overlay)

set -euo pipefail
. "$(dirname "${BASH_SOURCE[0]}")/duo2-env.sh"

PMOS_KEY=build.postmarketos.org.rsa.pub
PMOS_KEY_SHA256=b70e6ffc64a652d63aee0c28cb9ecb2ca3b49d759ca7a023bcb854d08780964b
PMOS_KEY_URL="https://gitlab.postmarketos.org/api/v4/projects/postmarketOS%2Fpmbootstrap/repository/files/pmb%2Fdata%2Fkeys%2F$PMOS_KEY/raw?ref=HEAD"
PMOS_REPO=https://mirror.postmarketos.org/postmarketos/master

BUILD="$LUMA_DUO2_ROOT/../build"
KEYS="$BUILD/pmos-keys"
MODULES="${LUMA_DUO2_MODULES_OUT:-$BUILD/duo2-modules}"
OUT="${LUMA_DUO2_INITRAMFS_OUT:-$BUILD/duo2-initramfs}"
DEVICEINFO="$LUMA_DUO2_ROOT/config/mobile/duo2-pmos-deviceinfo"

[ -d "$MODULES/lib/modules" ] || die "no staged modules -- run duo2-stage-modules.sh"
RELEASE="$(ls "$MODULES/lib/modules")"

mkdir -p "$KEYS" "$OUT"
if [ ! -f "$KEYS/$PMOS_KEY" ]; then
    info "fetching postmarketOS signing key"
    curl -sfL -o "$KEYS/$PMOS_KEY" "$PMOS_KEY_URL" || die "could not fetch $PMOS_KEY"
fi
echo "$PMOS_KEY_SHA256  $KEYS/$PMOS_KEY" | sha256sum -c --quiet - \
    || die "$PMOS_KEY does not match the pinned hash"

KEYS="$(cd "$KEYS" && pwd)"; MODULES="$(cd "$MODULES" && pwd)"; OUT="$(cd "$OUT" && pwd)"
rm -f "$OUT"/initramfs* "$OUT"/versions.txt

info "generating with postmarketOS mkinitfs for $RELEASE"
docker run --rm --platform linux/arm64 \
    -v "$KEYS:/keys:ro" -v "$MODULES/lib/modules:/modules:ro" \
    -v "$DEVICEINFO:/deviceinfo:ro" -v "$OUT:/out" \
    -e RELEASE="$RELEASE" -e PMOS_REPO="$PMOS_REPO" alpine:edge sh -euc '
cp /keys/*.pub /etc/apk/keys/
echo "$PMOS_REPO" >> /etc/apk/repositories
apk update -q >/dev/null
apk add -q postmarketos-initramfs postmarketos-mkinitfs
# mkinitfs copies these from the build root (one archive, so the "extra"
# list is included too). postmarketos-initramfs depends on the packages that
# provide them, but postmarketOS has a merged /usr and Alpine edge may still
# install to /sbin, /bin or /lib -- so a missing path is first looked for on
# the other side of /usr and copied (not linked: the initramfs needs the file
# itself), and only then installed by name.
for f in $(sed -e "s/#.*//" -e "s/[:!].*//" /usr/share/mkinitfs/files/*.files \
               /usr/share/mkinitfs/files-extra/*.files | sort -u); do
    case "$f" in /usr/share/*|/etc/*|*"*"*) continue ;; esac
    [ -e "$f" ] && continue
    case "$f" in /usr/*) alt="${f#/usr}" ;; *) alt="/usr$f" ;; esac
    # eudev keeps its config where systemd-udev keeps defaults.
    [ "$f" = /usr/lib/udev/udev.conf ] && alt=/etc/udev/udev.conf
    if [ -e "$alt" ]; then
        mkdir -p "${f%/*}"; cp -aL "$alt" "$f"; continue
    fi
    apk add -q "${f##*/}" 2>/dev/null || apk add -q "cmd:${f##*/}" 2>/dev/null || true
    [ -e "$f" ] || { echo "nothing provides $f" >&2; exit 1; }
done
install -D -m 0644 /deviceinfo /usr/share/deviceinfo/deviceinfo
mkdir -p /lib/modules /usr/share/kernel/duo2
cp -a "/modules/$RELEASE" /lib/modules/
echo "$RELEASE" > /usr/share/kernel/duo2/kernel.release
# mkinitfs writes the archives to a temporary work directory and hands them
# to boot-deploy, which on postmarketOS also builds the boot image; with
# -no-bootdeploy they are simply discarded. Our boot image is built by
# duo2-mkboot.sh, so this stand-in only copies the archives out.
cat > /usr/local/bin/boot-deploy <<"SHIM"
#!/bin/sh
src= dst=
while [ $# -gt 0 ]; do
    case "$1" in -d) src=$2; shift ;; -o) dst=$2; shift ;; esac
    shift
done
cp "$src"/initramfs* "$dst"/
SHIM
chmod +x /usr/local/bin/boot-deploy
mkinitfs -d /out
apk list -I postmarketos-initramfs postmarketos-mkinitfs busybox eudev 2>/dev/null \
    | sort > /out/versions.txt
'
ls -la "$OUT"
info "package versions:"; sed 's/^/    /' "$OUT/versions.txt"

# --- The Duo 2 overlay -------------------------------------------------------
# A second archive, appended: the kernel unpacks them in order and a later
# file replaces an earlier one -- the same mechanism as Luma's FP6 overlay.
# It replaces /init with a wrapper that starts duo2-home's watchdog and then
# execs postmarketOS's own init (carried unmodified as /init.pmos), and adds
# duo2-home as /usr/bin/bootloader for the debug shell.
SRC="$LUMA_DUO2_ROOT/kernel/initramfs"
GEN_INIT_CPIO="$LUMA_DUO2_ROOT/build/host/gen_init_cpio"
[ -x "$GEN_INIT_CPIO" ] || die "no $GEN_INIT_CPIO -- run duo2-mkinitramfs.sh once"
STAGE="$(mktemp -d)"; trap 'rm -rf "$STAGE"' EXIT
"${CROSS_COMPILE:-aarch64-linux-gnu-}gcc" -static -Os -Wall -o "$STAGE/duo2-home" "$SRC/duo2-home.c"
"${CROSS_COMPILE:-aarch64-linux-gnu-}strip" "$STAGE/duo2-home"
( cd "$STAGE" && zcat "$OUT/initramfs" | cpio -i --quiet init ) || die "no /init in the postmarketOS archive"
# busybox ash, as postmarketOS's own /init uses: /bin/sh does not exist yet.
cat > "$STAGE/init-wrapper" <<'WRAP'
#!/bin/busybox ash
# Luma Duo 2 overlay: start the way home, then postmarketOS's init as PID 1.
/usr/bin/duo2-home --watch
exec /init.pmos "$@"
WRAP
cat > "$STAGE/list" <<LIST
file /init $STAGE/init-wrapper 0755 0 0
file /init.pmos $STAGE/init 0755 0 0
dir /usr 0755 0 0
dir /usr/bin 0755 0 0
file /usr/bin/duo2-home $STAGE/duo2-home 0755 0 0
file /usr/bin/bootloader $STAGE/duo2-home 0755 0 0
LIST
"$GEN_INIT_CPIO" "$STAGE/list" | gzip -9 > "$OUT/overlay.cpio.gz"
cat "$OUT/initramfs" "$OUT/overlay.cpio.gz" > "$OUT/initramfs-luma"
info "overlay $(stat -c%s "$OUT/overlay.cpio.gz") bytes -> $OUT/initramfs-luma ($(stat -c%s "$OUT/initramfs-luma") bytes)"
